"""Regression tests for corrupt input, false PASS results and driver cleanup."""

from pathlib import Path
import sys
import tempfile
from types import SimpleNamespace as NS
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'tools'))
from hfi_a9 import A9Decoder
from check_sensors import StreamStats, driver_process, validate_image, validate_imu, validate_scan


# Original HFI-A9 bytes captured on 2026-11-04, not generated by the decoder.
ATTITUDE = bytes.fromhex('aa551423440f00774182a5f73a1f3e5a2bfbbeec2abd41764d')
MOTION = bytes.fromhex(
    'aa552c29440f00ce4e82a5806eee39201d983ae6b1bc3a'
    '194a5c3c7e92dbbadf1d87bf9c5f533e6f8a893da249ffbed14c')


class DecoderTests(unittest.TestCase):
    def test_real_frames_split_at_every_byte(self):
        decoder = A9Decoder()
        frames = []
        for byte in b'noise\xaa' + ATTITUDE + MOTION:
            frames.extend(decoder.feed(bytes([byte])))
        self.assertEqual([frame['kind'] for frame in frames], ['attitude', 'motion'])
        self.assertAlmostEqual(frames[0]['values'][2], 23.65, delta=0.1)
        self.assertAlmostEqual(frames[1]['values'][5], -1.0556, delta=0.01)
        self.assertEqual(decoder.crc_errors, 0)

    def test_corrupt_frame_rejected_and_next_frame_recovered(self):
        bad = bytearray(MOTION)
        bad[20] ^= 0x80
        decoder = A9Decoder()
        frames = decoder.feed(bytes(bad) + ATTITUDE + MOTION)
        self.assertEqual(decoder.crc_errors, 1)
        self.assertEqual([frame['kind'] for frame in frames], ['attitude', 'motion'])

    def test_truncated_frame_waits_for_remaining_bytes(self):
        decoder = A9Decoder()
        self.assertEqual(decoder.feed(MOTION[:-1]), [])
        self.assertEqual(len(decoder.feed(MOTION[-1:])), 1)


class StreamTests(unittest.TestCase):
    def stream(self, timestamps=None, valid=True):
        stats = StreamStats()
        for i in range(80):
            stamp = i + 1 if timestamps is None else timestamps[i]
            stats.add(valid, {}, stamp, 10 + i / 10)
        return stats

    def test_live_valid_stream_passes(self):
        self.assertEqual(self.stream().summary(18, 8)['status'], 'PASS')

    def test_old_data_is_not_a_pass(self):
        self.assertEqual(self.stream().summary(22, 8)['status'], 'FAIL')

    def test_frozen_timestamps_are_not_a_pass(self):
        result = self.stream([7] * 80).summary(18, 8)
        self.assertEqual(result['status'], 'FAIL')
        self.assertEqual(result['timestamp_errors'], 79)

    def test_invalid_data_is_not_a_pass(self):
        self.assertEqual(self.stream(valid=False).summary(18, 8)['status'], 'FAIL')

    def test_hardware_timestamp_wrap_is_supported(self):
        stats = StreamStats()
        stats.add(True, {}, 0xFFFFFFFE, 1, wrap32=True)
        stats.add(True, {}, 2, 1.1, wrap32=True)
        self.assertEqual(stats.stamp_errors, 0)
        stats.add(True, {}, 2, 1.2, wrap32=True)
        self.assertEqual(stats.stamp_errors, 1)


class PayloadTests(unittest.TestCase):
    def test_camera_imu_requires_gyro_and_acceleration_not_orientation(self):
        imu = NS(angular_velocity=NS(x=0., y=0., z=0.),
                 linear_acceleration=NS(x=0., y=0., z=9.81),
                 angular_velocity_covariance=[0.] * 9,
                 linear_acceleration_covariance=[0.] * 9,
                 orientation_covariance=[-1.] + [0.] * 8)
        self.assertTrue(validate_imu(imu)[0])
        imu.angular_velocity.x = float('nan')
        self.assertFalse(validate_imu(imu)[0])
        imu.angular_velocity.x = 0.
        imu.linear_acceleration.z = 0.
        self.assertFalse(validate_imu(imu)[0])
        imu.linear_acceleration.z = 9.81
        imu.angular_velocity_covariance[0] = -1.
        self.assertFalse(validate_imu(imu)[0])

    def test_no_valid_lidar_returns_is_not_a_pass(self):
        scan = NS(range_min=0.1, range_max=10.0, ranges=[0.0, float('inf'), float('nan'), 11.0])
        self.assertFalse(validate_scan(scan)[0])
        scan.ranges.append(1.2)
        self.assertTrue(validate_scan(scan)[0])

    def test_zero_or_truncated_depth_is_not_a_pass(self):
        image = NS(width=16, height=16, encoding='16UC1', is_bigendian=False,
                   step=32, data=bytes(512))
        self.assertFalse(validate_image(image, depth=True)[0])
        image.data = b'\xe8\x03' * 256  # one meter
        valid, sample = validate_image(image, depth=True)
        self.assertTrue(valid)
        self.assertEqual(sample['min_m'], 1.0)
        image.data = image.data[:-1]
        self.assertFalse(validate_image(image, depth=True)[0])

    def test_big_endian_depth_with_row_padding(self):
        image = NS(width=1, height=2, encoding='16UC1', is_bigendian=True,
                   step=4, data=b'\x03\xe8\xff\xff' * 2)
        valid, sample = validate_image(image, depth=True)
        self.assertTrue(valid)
        self.assertEqual(sample['min_m'], 1.0)

    def test_dark_color_frame_still_counts_as_receivable(self):
        image = NS(width=2, height=2, encoding='rgb8', step=6, data=bytes(12))
        self.assertTrue(validate_image(image)[0])
        image.step = 0
        self.assertFalse(validate_image(image)[0])


class CleanupTests(unittest.TestCase):
    def test_driver_stops_when_measurement_raises(self):
        with tempfile.TemporaryDirectory() as directory:
            process = None
            with self.assertRaisesRegex(RuntimeError, 'measurement failed'):
                with driver_process([sys.executable, '-c', 'import time; time.sleep(60)'],
                                    None, Path(directory) / 'driver.log') as process:
                    raise RuntimeError('measurement failed')
            self.assertIsNotNone(process.poll())


if __name__ == '__main__':
    unittest.main()
